#[tokio::test]
async fn test_error_non_2xx() {
    // Verify that non-2xx responses result in errors
    let addr = mock_error_server(400);
    let client = Client::new(&addr).with_api_key("test-key").with_max_retries(0);
    let result = client.fork_repository(&serde_json::json!({}), None).await;
    // The reqwest-based client may or may not surface this as an error
    // depending on whether the operation deserializes the response.
    // At minimum the request should complete without panic.
    drop(result);
}
